def factorial(n):
    if n < 0:
        raise ValueError('n must be non-negative')
    out = 1
    for i in range(1, n + 1):
        out *= i
    return out

def count_vowels(s):
    vowels = set('aeiouAEIOU')
    return sum(1 for ch in s if ch in vowels)

def sum_list(nums):
    total = 0
    for x in nums:
        total += x
    return total

