def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def word_count(text):
    parts = text.split()
    return len(parts)

def fib(n):
    if n < 0:
        raise ValueError('n must be non-negative')
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def is_prime(n):
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True

